package com.bank.newesthire;

import java.time.LocalDate;
import java.util.*;
import java.util.logging.*;

public class NewestHireDemo {
    private static final Logger log = Logger.getLogger("NewestHire");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee("Rajesh", LocalDate.parse("2018-03-10")),
            new Employee("Priya", LocalDate.parse("2022-07-01")),
            new Employee("Amit", LocalDate.parse("2020-06-01")));
        NewestHireService service = new NewestHireService();

        log.info(() -> "Newest hire: " + service.mostRecent(staff)
            .map(Employee::getName).orElse("none"));
        log.info(() -> "Empty list : " + service.mostRecent(List.of())
            .map(Employee::getName).orElse("none"));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final LocalDate joinDate;
    Employee(String name, LocalDate joinDate) { this.name = name; this.joinDate = joinDate; }
    String getName() { return name; }
    LocalDate getJoinDate() { return joinDate; }
}

// ─── Would be in service/NewestHireService.java ───
class NewestHireService {
    Optional<Employee> mostRecent(List<Employee> staff) {
        return staff.stream()
            .max(Comparator.comparing(Employee::getJoinDate)   // latest date wins
                .thenComparing(Employee::getName));             // deterministic tie-break
    }
}
